Bugzilla says cached record data caused createRecord to send a normal record after local deletion instead of a tombstone. The later code adds markDeleted and an immediate deleted-ID set while cache cleanup is asynchronous. markDeleted(id) {
    this._deleted.add(id);
    setData(this.name, id, null).then(() => this._deleted.delete(id));
  },

  /**
   * Update an item from a record.
   *
   * @param {CryptoWrapper} record
   */
  async update(record) {
    await setData(this.name, record.id, record.cleartext);
  },

  /**
   * Determine whether a record with the specified ID exists.
   *
   * @param {string} id
   * @return {boolean}
   */
  async itemExists(id) {
    return id in (await this.getAllIDs());
  },
